-- Merge of main into merge/main-sync (2026-11-06): one numbering authority.
-- main's ERP-0009 table (per organization, doc_type, prefix) becomes the
-- company-wide series table of NumberingService (ADR-0011/0012: one company,
-- one organization). Generated by drizzle-kit, then hand-edited so existing
-- counters survive: rows of the same type are collapsed to the highest
-- counter, the owning module and period are filled before NOT NULL applies,
-- and each counter continues in its current period so no code is reissued.
ALTER TABLE "organization"."document_sequences" RENAME COLUMN "doc_type" TO "document_type";--> statement-breakpoint
DROP INDEX "organization"."document_sequences_org_type_uq";--> statement-breakpoint
DROP INDEX "organization"."document_sequences_org_idx";--> statement-breakpoint
DELETE FROM "organization"."document_sequences" AS seq
WHERE EXISTS (
	SELECT 1 FROM "organization"."document_sequences" AS other
	WHERE other."document_type" = seq."document_type"
	  AND (other."next_number" > seq."next_number"
	       OR (other."next_number" = seq."next_number" AND other."id" > seq."id"))
);--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ADD COLUMN "module" varchar(32) NOT NULL DEFAULT 'inventory';--> statement-breakpoint
UPDATE "organization"."document_sequences"
SET "module" = CASE WHEN "document_type" LIKE 'asset%' THEN 'assets' ELSE 'inventory' END;--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ALTER COLUMN "module" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ADD COLUMN "pattern" varchar(100);--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ADD COLUMN "reset_policy" text;--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ADD COLUMN "period_key" varchar(7) NOT NULL DEFAULT 'all';--> statement-breakpoint
-- The current period of each type's default reset policy (Asia/Jakarta), so
-- the counter continues instead of restarting at 1.
UPDATE "organization"."document_sequences"
SET "period_key" = CASE
	WHEN "document_type" = 'asset_borrowing' THEN to_char(now() AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM')
	WHEN "document_type" IN ('stock_movement', 'asset', 'asset_tool_set') THEN 'all'
	ELSE to_char(now() AT TIME ZONE 'Asia/Jakarta', 'YYYY')
END;--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ALTER COLUMN "period_key" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ADD COLUMN "updated_by" text;--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ADD COLUMN "deleted_at" bigint;--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" DROP COLUMN "organization_id";--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" DROP COLUMN "prefix";--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ALTER COLUMN "next_number" SET DATA TYPE bigint USING "next_number"::bigint;--> statement-breakpoint
UPDATE "organization"."document_sequences" SET "updated_at" = "created_at" WHERE "updated_at" IS NULL;--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ALTER COLUMN "updated_at" SET NOT NULL;--> statement-breakpoint
CREATE UNIQUE INDEX "document_sequences_type_uq" ON "organization"."document_sequences" ("document_type") WHERE deleted_at IS NULL;--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ADD CONSTRAINT "document_sequences_reset_policy_check" CHECK ("reset_policy" IS NULL OR "reset_policy" IN ('never', 'yearly', 'monthly'));--> statement-breakpoint
ALTER TABLE "organization"."document_sequences" ADD CONSTRAINT "document_sequences_next_number_check" CHECK ("next_number" > 0);
